using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Preserve EF Core 8 id format ("Product|123") for existing 500K documents
        optionsBuilder.UseCosmos(o =>
        {
            // If your connection string is configured elsewhere, keep that;
            // the key option here is EnableIdValueGeneration below.
        });
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we pin the old name to stay compatible.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed from "EntityType|KeyValue" to raw key.
            // Existing documents have ids like "Product|123". Pin the old format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();
        });

        // BREAKING CHANGE 3 — HasIndex() is not supported by the Cosmos provider.
        // It was silently ignored in EF Core 8 but now throws. Removed.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

