using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator"; pin the old name to stay compatible.
            // Without this, EF Core 9 writes "$type" and your direct SQL queries
            // (WHERE c.Discriminator = 'Product') will return zero results.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed from "EntityType|Key" to just the raw key.
            // Existing documents have id = "Product|123".  We map a CosmosId shadow property
            // to the JSON "id" and compute it in the old format so EF can find existing docs.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator((_, _) =>
                      new Microsoft.EntityFrameworkCore.ValueGeneration.StringValueGenerator());

            // BREAKING CHANGE 3 — HasIndex() is not supported by the Cosmos provider.
            // It was silently ignored in EF Core 8 but now throws.  Removed.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; } = "";

    // Explicit Cosmos document id to preserve the EF Core 8 format ("Product|<key>").
    // Existing 500K documents use this format; without it EF Core 9 would generate
    // just the raw key value, making lookups against old documents fail.
    public string CosmosId => $"Product|{Id}";
}

